// SMA1B: accumulate 6x6 triangle stiffness into global 8x8 matrix
// kij is 36-element vector: column-major 6x6
void sma1b(const std::vector<double>& kij, int grid_id, int npvt, int ifkgg, double temp) {
    // We'll assume ngrid contains 4 node IDs (1-based) for CQUAD4
    // Map triangle nodes to global DOFs: node i (1-based) -> DOFs 2*(i-1) and 2*(i-1)+1 (0-based)
    // Triangle has 3 nodes: we need their global DOF indices
    std::vector<int> tri_nodes = {common.ngrid[0], common.ngrid[1], common.ngrid[2]}; // 1-based
    std::vector<int> dof_map;
    for (int node : tri_nodes) {
        int i0 = node - 1; // 0-based node index
        dof_map.push_back(2 * i0);     // x-DOF
        dof_map.push_back(2 * i0 + 1); // y-DOF
    }

    // Now scatter 6x6 kij (column-major) into global_k_matrix (row-major Eigen)
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            int gi = dof_map[i];
            int gj = dof_map[j];
            // kij is stored column-major: index = j*6 + i
            double val = kij[j * 6 + i];
            global_k_matrix(gi, gj) += val;
        }
    }
}

// Compute 6x6 triangle stiffness in LOCAL coordinate system (x' along v1->v2, y' = perp in-plane)
// Then rotate to GLOBAL XY using proper T^T * k_local * T
// Nodes: 3 points, each [x,y] in global XY
Eigen::Matrix<double, 6, 6> compute_triangle_stiffness_local_to_global(
    const std::vector<std::vector<double>>& tri_nodes, // 3 nodes, each [x,y]
    double E, double nu, double t) {

    // Material matrix for plane stress
    double D11 = E / (1.0 - nu*nu);
    double D12 = nu * E / (1.0 - nu*nu);
    double D22 = D11;
    double D66 = E / (2.0 * (1.0 + nu));

    Eigen::Matrix<double, 3, 3> D;
    D << D11, D12, 0.0,
         D12, D22, 0.0,
         0.0, 0.0, D66;

    // Triangle vertices in global XY
    double x1 = tri_nodes[0][0], y1 = tri_nodes[0][1];
    double x2 = tri_nodes[1][0], y2 = tri_nodes[1][1];
    double x3 = tri_nodes[2][0], y3 = tri_nodes[2][1];

    // Local x' axis: v2 - v1
    double dx = x2 - x1;
    double dy = y2 - y1;
    double len = std::sqrt(dx*dx + dy*dy);
    if (len < 1e-15) {
        return Eigen::Matrix<double, 6, 6>::Zero();
    }
    double cx = dx / len;
    double sy = dy / len; // = sinθ for angle from X to x'
    // Local y' axis: rotate x' by +90° → [-sy, cx]
    double sx = -sy;
    double cy = cx;

    // Rotation matrix from local (x',y') to global (X,Y): t = [[cx, -sx], [sx, cx]]
    // Because: [X,Y]^T = t * [x',y']^T
    // So displacement transformation: u_global = T * u_local, where T = blkdiag(t,t,t)
    Eigen::Matrix<double, 2, 2> t;
    t << cx, -sx,
         sx,  cy;

    // Build 6x6 T = [t,0,0; 0,t,0; 0,0,t]
    Eigen::Matrix<double, 6, 6> T = Eigen::Matrix<double, 6, 6>::Zero();
    for (int i = 0; i < 3; i++) {
        T.block<2,2>(2*i, 2*i) = t;
    }

    // Area of triangle
    double area = 0.5 * std::abs((x2-x1)*(y3-y1) - (x3-x1)*(y2-y1));
    if (area < 1e-15) return Eigen::Matrix<double, 6, 6>::Zero();

    // Strain-displacement matrix B (3x6) in LOCAL coordinates
    // For linear triangle: B = 1/(2*area) * [ (y2-y3), 0, (y3-y1), 0, (y1-y2), 0;
    //                                          0, (x3-x2), 0, (x1-x3), 0, (x2-x1);
    //                                          (x3-x2), (y2-y3), (x1-x3), (y3-y1), (x2-x1), (y1-y2) ]
    double y23 = y2 - y3;
    double y31 = y3 - y1;
    double y12 = y1 - y2;
    double x32 = x3 - x2;
    double x13 = x1 - x3;
    double x21 = x2 - x1;

    double fac = 1.0 / (2.0 * area);
    Eigen::Matrix<double, 3, 6> B_local;
    B_local << y23, 0.0, y31, 0.0, y12, 0.0,
               0.0, x32, 0.0, x13, 0.0, x21,
               x32, y23, x13, y31, x21, y12;
    B_local *= fac;

    // Local stiffness: k_local = t * area * B_local^T * D * B_local
    Eigen::Matrix<double, 6, 6> k_local = t * area * B_local.transpose() * D * B_local;

    // Rotate to global: k_global = T^T * k_local * T
    Eigen::Matrix<double, 6, 6> k_global = T.transpose() * k_local * T;

    return k_global;
}

