        {0.0, 0.0}, // node 1
        {2.0, 0.0}, // node 2
        {2.0, 1.5}, // node 3
        {0.0, 1.5}  // node 4
    };

    double E = 200e9;
    double nu = 0.3;
    double t_plate = 0.01;

    std::vector<std::vector<double>> tri_nodes;
    if (flag == 1) {
        // triangle 1: nodes 1,2,3 (0,1,2)
        tri_nodes = {nodes[0], nodes[1], nodes[2]};
        common.ngrid = {1, 2, 3, 4}; // 1-based node IDs
    } else if (flag == 2) {
        // triangle 2: nodes 1,3,4 (0,2,3)
        tri_nodes = {nodes[0], nodes[2], nodes[3]};
        common.ngrid = {1, 3, 4, 2}; // keep ngrid[0..2] as triangle nodes: 1,3,4
    } else {
        return;
    }

    // Compute 6x6 global triangle stiffness
    Eigen::Matrix<double, 6, 6> k_tri = compute_triangle_stiffness_local_to_global(tri_nodes, E, nu, t_plate);

    // Copy to kij (36 elements, column-major)
    std::vector<double> kij(36, 0.0);
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            kij[j * 6 + i] = k_tri(i, j); // column-major storage
        }
    }

    // Scatter into global matrix
    sma1b(kij, 0, 0, 0, 0.0);
}

